let codeLines = [];
let fontSize = 22;
let lineHeight = 30;
let margin = 70;

let scrollSpeed = 35; // frames between new lines
let frameCounter = 0;
let nextY;

// Typing state
let typingSpeed = 1; // frames per character
let typingCounter = 0;
let currentSnippet = "";
let currentIndex = 0;
let isTyping = false;

// Cursor
let cursorBlinkSpeed = 10;
let cursorVisible = true;
let cursorCounter = 0;
let cursorSize = 16;

let funSnippets = [
  "let _wG_1 = 0; while ((alive) && ++_wG_1 < 20000) { code(); }",
  "if(coffee) { awake = true; }",
