  "if(brain === null) { reboot(); }",
  "let _wG_6 = 0; while ((!coffee) && ++_wG_6 < 20000) { complain(); }",
  "const bug = features.pop();",
  "try { understand(); } catch(e) { google(); }",
  "for(let i = 0; i < deadline; i++) { panic++; }",
  "console.error('Reality not found');",
  "function refactor() { breakEverything(); }",
  "if(commit) { pray(); }",
  "let _wG_7 = 0; while ((stackOverflow) && ++_wG_7 < 20000) { copyPaste(); }",
  "return nap || coffee;",
  "<(• . • )>",
  "(•ㅅ•)",
  "(‾◡◝)",
	"O(∩_∩)O",
	"=.=",
	"(▀̿Ĺ̯▀̿ ̿)",
	"(￣o￣) . z Z"
];

function setup() {
  createCanvas(windowWidth, windowHeight);
  textFont("monospace");
  textSize(fontSize);
  frameRate(60);

  nextY = height / 2;
}

function draw() {
  background(0, 70);

  // Draw all lines
  for (let line of codeLines) {
    drawGlowingText(line.text, line.x, line.y);
  }

  // Cursor blink logic
  cursorCounter++;
  if (cursorCounter >= cursorBlinkSpeed) {
    cursorCounter = 0;
    cursorVisible = !cursorVisible;
  }

  // Start typing a new line after a pause
  frameCounter++;
  if (frameCounter >= scrollSpeed && !isTyping) {
    frameCounter = 0;
    startTyping();
  }

  // Type characters
  if (isTyping) {
    typeCharacter();
  }

  // Draw cursor
  if (cursorVisible && codeLines.length > 0) {
    drawCursor();
  }
}

// -------------------------
// Typing control
// -------------------------
function startTyping() {
  currentSnippet = random(funSnippets);
  currentIndex = 0;
  isTyping = true;

  codeLines.push({
    text: "",
    x: margin,
    y: nextY
  });
}

function typeCharacter() {
  typingCounter++;
  if (typingCounter < typingSpeed) return;
  typingCounter = 0;

  let currentLine = codeLines[codeLines.length - 1];
  currentLine.text += currentSnippet[currentIndex];
  currentIndex++;

  if (currentIndex >= currentSnippet.length) {
    isTyping = false;
    nextY += lineHeight;
    handleScroll();
  }
}

// -------------------------
// Scrolling logic
// -------------------------
function handleScroll() {
  if (nextY + lineHeight > height - margin) {
    for (let line of codeLines) {
      line.y -= lineHeight;
    }
    nextY -= lineHeight;
  }

  codeLines = codeLines.filter(
    line => line.y > margin - lineHeight
  );
}

// -------------------------
// Cursor
// -------------------------
function drawCursor() {
  let lastLine = codeLines[codeLines.length - 1];
  let cursorX = lastLine.x + textWidth(lastLine.text) + 6;
  let cursorY = lastLine.y - fontSize + 4;

  drawingContext.shadowBlur = 6;
  drawingContext.shadowColor = color(0, 255, 70);

  noStroke();
  fill(0, 255, 70);
  rect(cursorX, cursorY, cursorSize, cursorSize);

  drawingContext.shadowBlur = 0;
}

// -------------------------
// Glowing text
// -------------------------
function drawGlowingText(txt, x, y) {
  for (let i = 4; i > 0; i--) {
    fill(0, 255, 70, 40 * i);
    text(txt, x, y);
  }
  fill(0, 255, 70);
  text(txt, x, y);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);

  // Clear all previous lines
  codeLines = [];

  // Reset typing state
  isTyping = false;
  currentSnippet = "";
  currentIndex = 0;
  typingCounter = 0;
  frameCounter = 0;

  // Reset cursor
  cursorCounter = 0;
  cursorVisible = true;

  // Reset starting position
  nextY = height / 2;
}
